validations.command:
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
const history=[], shown=[], queued=[], records=[], cancels=[];
const pending=new Map();
const feed=createProgressFeed({initialPacket:'warm',decode:p=>pending.has(p)?pending.get(p).promise:p});
const workspace=createTransferWorkspace({transport(){},onCancel:x=>cancels.push(x.attemptId),record:x=>records.push(x),showQueued:x=>queued.push(x),recordProgress:x=>history.push(x),showProgress:x=>shown.push(x)});
const file={id:'a',progressFeed:feed};
workspace.select(file);
assert.deepEqual(shown.map(x=>x.frame),['warm']);
for(const p of ['old','new']) { let resolve; const promise=new Promise(r=>resolve=r); pending.set(p,{promise,resolve}); feed.emit(p); }
pending.get('new').resolve('new frame'); await Promise.resolve();
pending.get('old').resolve('old frame'); await Promise.resolve();
assert.deepEqual(shown.map(x=>x.frame),['warm','new frame']);
assert.deepEqual(history.map(x=>x.frame),['warm','new frame','old frame']);
workspace.retry();
assert.deepEqual(queued.map(x=>x.attemptId),[1,2]);
assert.deepEqual(records.map(x=>x.kind),['select','retry']);
assert.equal(shown.at(-1).frame,'warm');
workspace.hide(); feed.emit('hidden'); assert.equal(shown.at(-1).frame,'warm');
workspace.select(file); assert.equal(shown.at(-1).frame,'warm');
workspace.dispose(); assert.deepEqual(cancels,[1,2,3]);
const deltas=[]; const diagnostic=createProgressFeed({initialPacket:'cached'});
const stop=collectProgressTelemetry(diagnostic,x=>deltas.push(x));
diagnostic.emit('live'); stop(); diagnostic.emit('after');
assert.deepEqual(deltas,['live']);
let reentrant; const refeed=createProgressFeed({initialPacket:'first',onDetach:()=>{}});
const ws=createTransferWorkspace({transport(){},onCancel(){},record(){},showQueued(){},recordProgress(){},showProgress(){reentrant.hide();}});
reentrant=ws; ws.select({id:'b',progressFeed:refeed});
assert.equal(ws.snapshot().visitId,null);
console.log('progress scenarios passed');
EOF
